import{_ as t,a0 as o,w as r,s as d,ao as l,I as i,x as a,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"使用 Lua 解析配置文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Lua 解析配置文件 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Lua 解析配置文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Lua 解析配置文件 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20210623 Parsing config files with Lua","title":"使用 Lua 解析配置文件","tag":"202211","desc":""},"relativePath":"202211/20210623 Parsing config files with Lua.md","filePath":"[post].md"}'),c={name:"202211/20210623 Parsing config files with Lua.md"};function u(h,s,g,k,f,b){const n=o("Link");return r(),d("div",null,[s[35]||(s[35]=l('<h1 id="使用-lua-解析配置文件" tabindex="-1">使用 Lua 解析配置文件 <a class="header-anchor" href="#使用-lua-解析配置文件" aria-label="Permalink to “使用 Lua 解析配置文件”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/10/084609uq6vvp1vjzqzpc9k.jpg" alt=""></p><blockquote><p>使用 Lua 配置持久化應用設置。</p></blockquote><p>不是所有的應用都需要配置文件；對很多應用來説，在啓動時變得煥然一新對它們更有利。例如，簡單的工具就極少需要偏好項和設置在使用過程中保持穩定不變。然而，當你編寫一個複雜的應用程序時，如果能讓用户設置與應用的交互方式，以及應用與系統交互的方式會很不錯。這就是配置文件用來做的事情。本文將討論一些利用 Lua 進行持久化配置的方法。</p><h3 id="選擇一種格式" tabindex="-1">選擇一種格式 <a class="header-anchor" href="#選擇一種格式" aria-label="Permalink to “選擇一種格式”">​</a></h3><p>關於配置文件很重要的兩點是一致性和可預見性。你不會希望為了保存用户偏好項，將信息轉儲到文件中，然後再花幾天去編碼實現“逆向工程”，處理最後出現在文件裏的隨機信息。</p>',6)),i("p",null,[s[1]||(s[1]=a("這裏用一些常用的 ",-1)),e(n,{href:"https://opensource.com/article/21/6/config-files-and-their-formats"},{default:p(()=>[...s[0]||(s[0]=[a("配置文件格式",-1)])]),_:1}),s[2]||(s[2]=a("。Lua 有一些庫可以處理大多數常用的配置格式；在本文中，我會採用 INI 格式。",-1))]),s[36]||(s[36]=i("h3",{id:"安裝庫",tabindex:"-1"},[a("安裝庫 "),i("a",{class:"header-anchor",href:"#安裝庫","aria-label":"Permalink to “安裝庫”"},"​")],-1)),i("p",null,[s[4]||(s[4]=a("Lua 庫的核心倉庫是 ",-1)),e(n,{href:"https://opensource.com/article/19/11/getting-started-luarocks"},{default:p(()=>[...s[3]||(s[3]=[a("Luarocks.org",-1)])]),_:1}),s[5]||(s[5]=a("。你可以在這個網站搜索庫，或者你可以安裝並使用 ",-1)),s[6]||(s[6]=i("code",null,"luarocks",-1)),s[7]||(s[7]=a(" 終端命令。",-1))]),s[37]||(s[37]=l('<p>Linux 環境中，你可以從發行版的軟件倉庫中下載它，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install luarocks</span></span></code></pre></div>',2)),i("p",null,[s[11]||(s[11]=a("在 macOS 上，請使用 ",-1)),e(n,{href:"https://opensource.com/article/20/11/macports"},{default:p(()=>[...s[8]||(s[8]=[a("MacPorts",-1)])]),_:1}),s[12]||(s[12]=a(" 或者 ",-1)),e(n,{href:"https://opensource.com/article/20/6/homebrew-mac"},{default:p(()=>[...s[9]||(s[9]=[a("Homebrew",-1)])]),_:1}),s[13]||(s[13]=a("。在 Windows 上，請使用 ",-1)),e(n,{href:"https://opensource.com/article/20/3/chocolatey"},{default:p(()=>[...s[10]||(s[10]=[a("Chocolatey",-1)])]),_:1}),s[14]||(s[14]=a("。",-1))]),s[38]||(s[38]=l(`<p><code>luarocks</code> 安裝後，你可以使用 <code>search</code> 子命令來搜索一個恰當的庫。如果你不知道庫的名字，可以通過關鍵詞來搜索這個庫，例如 <code>ini</code>、xml<code>或者</code>json<code>，這取決於你想要用這個庫做什麼。打個比方，你可以搜索 </code>inifile\`， 這個庫被我用來解析 INI 格式的文本文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ luarocks search inifile</span></span>
<span class="line"><span>Search results:</span></span>
<span class="line"><span>inifile</span></span>
<span class="line"><span> 1.0-2 (rockspec) - https://luarocks.org</span></span>
<span class="line"><span> 1.0-2 (src) - https://luarocks.org</span></span>
<span class="line"><span> 1.0-1 (rockspec) - https://luarocks.org</span></span>
<span class="line"><span> [...]</span></span></code></pre></div><p>一個開發者容易犯的錯誤是在系統上安裝了這個庫卻忘了把它和應用打包。這會給沒有安裝這個庫的用户帶來麻煩。為了防止這個問題發生，可以使用 <code>--tree</code> 選項將它安裝在項目的本地文件夾中。如果你沒有這個項目文件夾，那就先創建這個文件夾再安裝庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir demo</span></span>
<span class="line"><span>$ cd demo</span></span>
<span class="line"><span>$ luarocks install --tree=local inifile</span></span></code></pre></div><p><code>--tree</code> 選項指示 <code>luarocks</code> 創建一個新文件夾並在其中安裝你的庫，例如這個例子中的 <code>local</code> 文件夾。 使用這個簡單的技巧，你可以將所有你項目要使用的依賴項直接安裝到項目文件夾中。</p><h3 id="配置代碼" tabindex="-1">配置代碼 <a class="header-anchor" href="#配置代碼" aria-label="Permalink to “配置代碼”">​</a></h3><p>首先，在一個名 <code>myconfig.ini</code> 的文件中創建一些 INI 數據。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[example]</span></span>
<span class="line"><span>name=Tux</span></span>
<span class="line"><span>species=penguin</span></span>
<span class="line"><span>enabled=false</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[demo]</span></span>
<span class="line"><span>name=Beastie</span></span>
<span class="line"><span>species=demon</span></span>
<span class="line"><span>enabled=false</span></span></code></pre></div><p>將這個文件保存到你的主目錄下，命名為 <code>myconfig.ini</code>, <em>不要</em> 存到項目文件夾下。你通常會希望配置文件獨立於你的文件存在，這樣當用户卸載你的應用時，使用應用時產生的數據可以保存在系統中。有些用户會刪除不重要的配置文件，但大多數不會。最終，如果他們要重裝這個應用，還會保留着所有的用户偏好項。</p>`,9)),i("p",null,[s[16]||(s[16]=a("配置文件的位置以技術來説並不重要，但每一個操作系統都有存儲它們的特定或者默認的路徑。在 Linux 中，這個路徑由 ",-1)),e(n,{href:"https://www.freedesktop.org/wiki/Specifications"},{default:p(()=>[...s[15]||(s[15]=[a("Freedesktop 規範",-1)])]),_:1}),s[17]||(s[17]=a(" 指定。它規定配置文件被保存在一個名為 ",-1)),s[18]||(s[18]=i("code",null,"~/.config",-1)),s[19]||(s[19]=a(" 的隱藏文件夾中。為了操作時更加清晰明確，可以在主目錄下存儲配置文件，以便於使用和尋找。",-1))]),s[39]||(s[39]=l(`<p>創建第二個文件，命名為 <code>main.lua</code>，並在你喜歡的文本編輯器中打開它。</p><p>首先，你必須告訴 Lua 你將想要使用的附加庫放置在哪裏。<code>package.path</code> 變量決定了 Lua 到哪裏去尋找這些庫。你可以從終端中查看 Lua 默認的包地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ Lua</span></span>
<span class="line"><span>&gt; print(package.path)</span></span>
<span class="line"><span>./?.lua;/usr/share/lua/5.3/?.lua;/usr/share/lua/5.3/?/init.lua;/usr/lib64/lua/5.3/?.lua;/usr/lib64/lua/5.3/?/init.lua</span></span></code></pre></div><p>在你的 Lua 代碼中，將你本地庫的路徑添加到 <code>package.path</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>package.path = package.path .. &#39;;local/share/lua/5.3/?.lua</span></span></code></pre></div><h3 id="使用-lua-解析-ini-文件" tabindex="-1">使用 Lua 解析 INI 文件 <a class="header-anchor" href="#使用-lua-解析-ini-文件" aria-label="Permalink to “使用 Lua 解析 INI 文件”">​</a></h3><p>當包的位置確定以後，下一件事就是引入 <code>inifile</code> 庫並處理一些操作系統邏輯。即使這是一個很簡單的應用，代碼也需要從操作系統獲取到用户主目錄的路徑，並建立在必要時將文件系統路徑返回給操作系統的通信方式。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>package.path = package.path .. &#39;;local/share/lua/5.3/?.lua</span></span>
<span class="line"><span>inifile = require(&#39;inifile&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- find home directory</span></span>
<span class="line"><span>home = os.getenv(&#39;HOME&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- detect path separator</span></span>
<span class="line"><span>-- returns &#39;/&#39; for Linux and Mac</span></span>
<span class="line"><span>-- and &#39;\\&#39; for Windows</span></span>
<span class="line"><span>d = package.config:sub(1,1)</span></span></code></pre></div><p>現在你可使用 <code>inifile</code> 來從配置文件解析數據到 Lua 表中。一旦這些數據被導入進表中，你可以像查詢其他的 Lua 表一樣查詢它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-- parse the INI file and</span></span>
<span class="line"><span>-- put values into a table called conf</span></span>
<span class="line"><span>conf = inifile.parse(home .. d .. &#39;myconfig.ini&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- print the data for review</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;name&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;species&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;enabled&#39;])</span></span></code></pre></div><p>在終端中運行代碼可以看見結果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lua ./main.lua</span></span>
<span class="line"><span>Tux</span></span>
<span class="line"><span>penguin</span></span>
<span class="line"><span>false</span></span></code></pre></div><p>這看起來是正確的。試試在 <code>demo</code> 塊中執行同樣的操作。</p><h3 id="使用-ini-格式存儲數據" tabindex="-1">使用 INI 格式存儲數據 <a class="header-anchor" href="#使用-ini-格式存儲數據" aria-label="Permalink to “使用 INI 格式存儲數據”">​</a></h3><p>不是所有用來解析的庫都會讀寫數據（通常被稱為 _編碼 和 <em>解碼</em>），但是 <code>inifile</code> 會這樣做。這意味着你可以使用它對配置文件進行修改。</p><p>為了改變配置文件中的值，你可以對被解析的表中的變量進行設置，然後把表重寫回配置文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>-- set enabled to true</span></span>
<span class="line"><span>conf[&#39;example&#39;][&#39;enabled&#39;] = true</span></span>
<span class="line"><span>conf[&#39;demo&#39;][&#39;enabled&#39;] = true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- save the change</span></span>
<span class="line"><span>inifile.save(home .. d .. &#39;myconfig.ini&#39;, conf)</span></span></code></pre></div><p>現在再來看看配置文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/myconfig.ini</span></span>
<span class="line"><span>[example]</span></span>
<span class="line"><span>name=Tux</span></span>
<span class="line"><span>species=penguin</span></span>
<span class="line"><span>enabled=true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[demo]</span></span>
<span class="line"><span>name=Beastie</span></span>
<span class="line"><span>species=demon</span></span>
<span class="line"><span>enabled=true</span></span></code></pre></div><h3 id="配置文件" tabindex="-1">配置文件 <a class="header-anchor" href="#配置文件" aria-label="Permalink to “配置文件”">​</a></h3><p>按照用户的設想來存儲數據對程序來説是至關重要的。幸運的是，這對工程師來説是一個很常規的任務，大多數工作可能早已被完成了。只要找到一個好用的庫完成開放格式下編碼和解碼，你就能為用户提供一致且持續的體驗。</p><p>以下是完整的演示代碼，可供參考。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>package.path = package.path .. &#39;;local/share/lua/5.3/?.lua&#39;</span></span>
<span class="line"><span>inifile = require(&#39;inifile&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- find home directory</span></span>
<span class="line"><span>home = os.getenv(&#39;HOME&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- detect path separator</span></span>
<span class="line"><span>-- returns &#39;/&#39; for Linux and Mac</span></span>
<span class="line"><span>-- and &#39;\\&#39; for Windows</span></span>
<span class="line"><span>d = package.config:sub(1,1)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- parse the INI file and</span></span>
<span class="line"><span>-- put values into a table called conf</span></span>
<span class="line"><span>conf = inifile.parse(home .. d .. &#39;myconfig.ini&#39;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- print the data for review</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;name&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;species&#39;])</span></span>
<span class="line"><span>print(conf[&#39;example&#39;][&#39;enabled&#39;])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- enable Tux</span></span>
<span class="line"><span>conf[&#39;example&#39;][&#39;enabled&#39;] = true</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- save the change</span></span>
<span class="line"><span>inifile.save(home .. d .. &#39;myconfig.ini&#39;, conf)</span></span></code></pre></div><hr>`,24)),i("p",null,[s[21]||(s[21]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/6/parsing-config-files-lua"},{default:p(()=>[...s[20]||(s[20]=[a("https://opensource.com/article/21/6/parsing-config-files-lua",-1)])]),_:1})]),i("p",null,[s[26]||(s[26]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...s[22]||(s[22]=[a("Seth Kenlon",-1)])]),_:1}),s[27]||(s[27]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...s[23]||(s[23]=[a("lujun9972",-1)])]),_:1}),s[28]||(s[28]=a(" 譯者：",-1)),e(n,{href:"https://github.com/hadisi1993"},{default:p(()=>[...s[24]||(s[24]=[a("hadisi1993",-1)])]),_:1}),s[29]||(s[29]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[25]||(s[25]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[32]||(s[32]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[30]||(s[30]=[a("LCTT",-1)])]),_:1}),s[33]||(s[33]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[31]||(s[31]=[a("Linux中國",-1)])]),_:1}),s[34]||(s[34]=a(" 榮譽推出",-1))])])}const C=t(c,[["render",u]]);export{y as __pageData,C as default};
